<?php
require_once __DIR__.'/../config/auth.php'; ensure_assessment_tables();require_login();$uid=user()['id'];
$provas=db()->query("SELECT p.*,COUNT(q.id) perguntas FROM provas p LEFT JOIN prova_perguntas q ON q.prova_id=p.id WHERE p.publicada=1 GROUP BY p.id ORDER BY p.created_at DESC")->fetchAll();
$hist=$st=db()->prepare("SELECT t.*,p.titulo,p.disciplina FROM prova_tentativas t JOIN provas p ON p.id=t.prova_id WHERE t.usuario_id=? AND t.status IN ('finalizada','expirada') ORDER BY t.finalizado_em DESC");$st->execute([$uid]);$hist=$st->fetchAll();
$pageTitle='Provas';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><section class="panel"><h2>Provas disponíveis</h2><div class="book-grid"><?php foreach($provas as $p):$done=db()->prepare('SELECT * FROM prova_tentativas WHERE prova_id=? AND usuario_id=?');$done->execute([$p['id'],$uid]);$attempt=$done->fetch();?><article class="card" style="padding:20px"><span class="badge"><?=e($p['disciplina'])?></span><h3><?=e($p['titulo'])?></h3><p class="subtext"><?=e($p['descricao'])?></p><p><b><?=$p['perguntas']?></b> questão(ões) · <b><?=$p['duracao_minutos']?> min</b></p><?php if($attempt):?><div class="notice success">Você já realizou esta prova. Nota: <b><?=number_format($attempt['nota'],1,',','.')?></b>/10</div><a class="btn btn-outline" href="<?=base_url('aluno/resultado-prova.php?id='.$attempt['id'])?>">Ver resultado</a><?php else:?><a class="btn" href="<?=base_url('aluno/prova.php?id='.$p['id'])?>">Iniciar prova</a><?php endif;?></article><?php endforeach;?><?php if(!$provas):?><div class="empty">Nenhuma prova publicada no momento.</div><?php endif;?></div></section>
<section class="panel"><h2>Histórico de notas</h2><div class="table-wrap"><table><thead><tr><th>Prova</th><th>Disciplina</th><th>Acertos</th><th>Nota</th><th>Finalizada</th><th></th></tr></thead><tbody><?php foreach($hist as $h):?><tr><td><b><?=e($h['titulo'])?></b></td><td><?=e($h['disciplina'])?></td><td><?=$h['acertos']?>/<?=$h['total']?></td><td><span class="badge"><?=number_format($h['nota'],1,',','.')?></span></td><td><?=date('d/m/Y H:i',strtotime($h['finalizado_em']))?></td><td><a class="btn btn-small btn-outline" href="<?=base_url('aluno/resultado-prova.php?id='.$h['id'])?>">Resultado</a></td></tr><?php endforeach;?><?php if(!$hist):?><tr><td colspan="6" class="empty">Você ainda não realizou nenhuma prova.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
